def longest_fibonacci_subarray(nums):
    if len(nums)<3:return len(nums)
    answer=current=2
    for index in range(2,len(nums)):
        if nums[index]==nums[index-1]+nums[index-2]:current+=1;answer=max(answer,current)
        else:current=2
    return answer

